begin;
select plan(18);
select has_table('public','birth_registrations','births have a source-verified registry');
select has_table('public','death_registrations','deaths have a source-verified registry');
select has_column('public','birth_registrations','maternity_source_event_id','births can reference a maternity source event without assuming its schema');
select has_column('public','death_registrations','encounter_id','deaths link to emergency encounters');
select has_table('public','statutory_report_definitions','report definitions are versioned');
select has_table('public','statutory_report_suppression_rules','cell suppression is configurable');
select has_table('public','statutory_report_exports','exports retain disclosure details');
select has_function('public','register_birth',array['uuid','uuid','uuid','uuid','uuid','text','timestamp with time zone','text','integer','integer','text','text'],'birth registry RPC exists');
select has_function('public','register_death',array['uuid','uuid','uuid','text','uuid','timestamp with time zone','text'],'death registry RPC exists');
select has_function('public','verify_vital_registration',array['text','uuid','text','text'],'source verification is explicit');
select has_function('public','configure_statutory_report',array['uuid','text','text','jsonb','boolean'],'definitions can be versioned per facility');
select has_function('public','configure_statutory_small_cell_rule',array['uuid','integer','text'],'suppression thresholds are configured with a basis');
select has_function('public','aggregate_statutory_report',array['uuid','date','date'],'aggregate RPC is available');
select has_function('public','export_statutory_report',array['uuid','date','date','text','text'],'exports require recipient and purpose');
select has_trigger('public','statutory_report_exports','statutory_report_export_immutable','export disclosure entries are immutable');
select ok((select count(*)>0 from public.statutory_report_definitions where report_key='sample.vital_events' and official_mapping=false and definition->>'mapping_status'='illustrative_only'),'only a clearly illustrative sample definition is seeded');
select ok(not exists(select 1 from public.statutory_report_suppression_rules),'small-cell suppression is unset until facility configuration');
select ok(not exists(select 1 from public.permission_catalog where permission_key in ('vital_registry.manage','statutory_report.read') and not sensitive),'registry and reporting permissions are marked sensitive');
select ok(exists(select 1 from pg_constraint where conrelid='public.birth_registrations'::regclass and contype='c' and pg_get_constraintdef(oid) like '%verification_status%verified_by%verified_at%'),'birth verification state requires verifier identity and timestamp');
select * from finish();
rollback;
